package pe.edu.grupo4.carga.controller;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.context.annotation.Import; import org.springframework.test.web.servlet.MockMvc; import pe.edu.grupo4.carga.dto.*; import pe.edu.grupo4.carga.service.CargaAcademicaService; import pe.edu.grupo4.shared.exception.*; import pe.edu.grupo4.shared.exception.GlobalExceptionHandler; import java.time.*; import java.util.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(CargaAcademicaController.class) @Import(GlobalExceptionHandler.class) class CargaAcademicaControllerTest { @Autowired MockMvc mvc; @MockBean CargaAcademicaService service; private static final String BODY="{\"cicloAcademico\":\"2026-2\",\"docenteId\":1,\"cursoId\":1,\"seccion\":\"A\",\"sedeId\":1,\"diaSemana\":\"MONDAY\",\"horaInicio\":\"18:00\",\"horaFin\":\"20:00\"}";
 @Test void returns200ForListAndGet()throws Exception{when(service.listar(null,null,null)).thenReturn(List.of());mvc.perform(get("/api/v1/cargas-academicas")).andExpect(status().isOk()).andExpect(content().json("[]"));mvc.perform(get("/api/v1/cargas-academicas/1")).andExpect(status().isOk());}
 @Test void returns201ForCreate()throws Exception{when(service.crear(any())).thenReturn(response());mvc.perform(post("/api/v1/cargas-academicas").contentType("application/json").content(BODY)).andExpect(status().isCreated());}
 @Test void returns400ForInvalidBody()throws Exception{mvc.perform(post("/api/v1/cargas-academicas").contentType("application/json").content("{}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.timestamp").exists()).andExpect(jsonPath("$.path").value("/api/v1/cargas-academicas"));}
 @Test void returns404ForMissingItem()throws Exception{when(service.obtener(90L)).thenThrow(new RecursoNoEncontradoException("No existe"));mvc.perform(get("/api/v1/cargas-academicas/90")).andExpect(status().isNotFound()).andExpect(jsonPath("$.message").value("No existe"));}
 @Test void returns409ForBusinessConflict()throws Exception{when(service.crear(any())).thenThrow(new ConflictoNegocioException("Cruce horario detectado"));mvc.perform(post("/api/v1/cargas-academicas").contentType("application/json").content(BODY)).andExpect(status().isConflict()).andExpect(jsonPath("$.message").value("Cruce horario detectado"));}
 private CargaAcademicaResponse response(){return new CargaAcademicaResponse(1L,"2026-2",1L,"Ana Torres",1L,"POO","A",1L,"Miraflores",DayOfWeek.MONDAY,LocalTime.of(18,0),LocalTime.of(20,0),pe.edu.grupo4.carga.entity.CargaAcademica.EstadoCarga.ACTIVA,2);}
}
